sys_script_include.script:
var Get_user_details = Class.create();
Get_user_details.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getdetails : function(){

	var grUser = new GlideRecord('sys_user');
	grUser.addQuery('user_name',this.getParameter('user_name'));
	grUser.query();
	if (grUser.next()){
		var userdet = {};
		userdet.manager = grUser.manager.toString();
		userdet.department = grUser.department.toString();

		return JSON.stringify(userdet);
	}
	},

    type: 'Get_user_details'
});
